interface Analytics {
  views: number;
  uniqueVisitors: number;
  conversionRate: number;
}

interface Notification {
  id: number;
  message: string;
  read: boolean;
}

interface Settings {
  theme: string;
  notificationsEnabled: boolean;
}

async function getDashboardData() {
  try {
    const baseUrl = 'http://localhost:3000';
    const [analytics, notifications, settings] = await Promise.all([
      fetch(`${baseUrl}/api/analytics`).then(r => r.json()),
      fetch(`${baseUrl}/api/notifications`).then(r => r.json()),
      fetch(`${baseUrl}/api/settings`).then(r => r.json())
    ]);

    return { 
      analytics: analytics as Analytics, 
      notifications: notifications as Notification[], 
      settings: settings as Settings 
    };
  } catch {
    // Return mock data for build time or if API is unreachable
    return {
      analytics: { views: 5000, uniqueVisitors: 1200, conversionRate: 0.15 },
      notifications: [
        { id: 1, message: 'Welcome to the dashboard!', read: false },
        { id: 2, message: 'Your report is ready.', read: true }
      ],
      settings: { theme: 'light', notificationsEnabled: true }
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div className="p-4 border rounded-lg shadow-sm">
      <h2 className="text-2xl font-bold mb-4">Dashboard Content</h2>

      <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
        {/* Analytics Section */}
        <div className="p-4 bg-gray-50 rounded border">
          <h3 className="font-semibold text-lg mb-2">Analytics</h3>
          <ul className="space-y-1">
            <li>Views: {analytics.views.toLocaleString()}</li>
            <li>Visitors: {analytics.uniqueVisitors.toLocaleString()}</li>
            <li>Conversion: {(analytics.conversionRate * 100).toFixed(1)}%</li>
          </ul>
        </div>

        {/* Notifications Section */}
        <div className="p-4 bg-gray-50 rounded border">
          <h3 className="font-semibold text-lg mb-2">Notifications</h3>
          <ul className="space-y-2">
            {notifications.map(notif => (
              <li key={notif.id} className={`p-2 rounded ${notif.read ? 'bg-gray-100' : 'bg-blue-50 border-blue-100 border'}`}>
                {notif.message}
              </li>
            ))}
          </ul>
        </div>

        {/* Settings Section */}
        <div className="p-4 bg-gray-50 rounded border">
          <h3 className="font-semibold text-lg mb-2">Settings</h3>
          <ul className="space-y-1">
            <li>Theme: {settings.theme}</li>
            <li>Notifications: {settings.notificationsEnabled ? 'On' : 'Off'}</li>
          </ul>
        </div>
      </div>
    </div>
  );
}

